import { Currency, Token } from '@uniswap/sdk-core'
import type { ImageSourcePropType } from 'react-native'
import { CELO_LOGO, ETH_LOGO } from 'ui/src/assets'
import {
  ABX,
  ABX_ABSTRACT_MAINNET,
  ABX_ABSTRACT_TESTNET,
  DAI,
  USDC_MAINNET,
  USDC_SEPOLIA,
  USDC_ABSTRACT_MAINNET,
  USDC_ABSTRACT_TESTNET,
  USDT_ABSTRACT_MAINNET,
  USDT_ABSTRACT_TESTNET,
  AARON_ABSTRACT_TESTNET,
  USDT,
  WBTC,
  WETH_ABSTRACT_MAINNET,
  WETH_ABSTRACT_TESTNET,
  WRAPPED_NATIVE_CURRENCY,
  isCelo,
  nativeOnChain,
} from 'uniswap/src/constants/tokens'
import { ProtectionResult } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { getChainInfo } from 'uniswap/src/features/chains/chainInfo'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo, TokenList } from 'uniswap/src/features/dataApi/types'
import { buildCurrencyInfo } from 'uniswap/src/features/dataApi/utils'
import { getTokenLogoUrl } from 'uniswap/src/constants/tokenLogos'
import { isSameAddress } from 'utilities/src/addresses'

type ChainCurrencyList = {
  readonly [chainId: number]: CurrencyInfo[]
}

/**
 * @deprecated
 * Instead, see the list used in the token selector's quick-select common options section at useAllCommonBaseCurrencies.ts.
 * This list is currently used as fallback list when Token GQL query fails for above list + for hardcoded tokens on testnet chains.
 */
export const COMMON_BASES: ChainCurrencyList = {
  [UniverseChainId.Mainnet]: [
    nativeOnChain(UniverseChainId.Mainnet),
    WETH_ABSTRACT_MAINNET,
    USDC_ABSTRACT_MAINNET,
    USDT_ABSTRACT_MAINNET,
    ABX_ABSTRACT_MAINNET,
  ].map(buildPartialCurrencyInfo),

  [UniverseChainId.Sepolia]: [
    nativeOnChain(UniverseChainId.Sepolia),
    WETH_ABSTRACT_TESTNET,
    USDC_ABSTRACT_TESTNET,
    ABX_ABSTRACT_TESTNET,
    USDT_ABSTRACT_TESTNET,
    AARON_ABSTRACT_TESTNET,
  ].map(buildPartialCurrencyInfo),
}

const alwaysShowList: TokenList = [USDC_ABSTRACT_MAINNET, USDC_ABSTRACT_TESTNET]

// Used to overwrite token logos on the interface
// Note: We use SafetyLevel.Blocked for tokens that have a warning image
//       since we need to differentiate between the two
export type LogoTable = Readonly<{
  [key: string]: Readonly<{
    logoUrl: string | ImageSourcePropType
    safetyLevel: ProtectionResult
  }>
}>

function getNativeLogoURI(chainId: UniverseChainId = UniverseChainId.Mainnet): ImageSourcePropType | string {
  return getChainInfo(chainId).nativeCurrency.logo ?? ETH_LOGO
}

function getTokenLogoURI(chainId: UniverseChainId, address: string): ImageSourcePropType | string | undefined {
  const chainInfo = getChainInfo(chainId)
  const networkName = chainInfo?.assetRepoNetworkName

  if (isCelo(chainId) && isSameAddress(address, nativeOnChain(chainId).wrapped.address)) {
    return CELO_LOGO as ImageSourcePropType
  }

  // For Abstract chains, use our custom logo mapping first
  if (chainId === UniverseChainId.Mainnet || chainId === UniverseChainId.Sepolia) {
    const abstractLogo = getTokenLogoUrl(address)
    if (abstractLogo) {
      return abstractLogo
    }
  }

  return networkName
    ? `https://raw.githubusercontent.com/Uniswap/assets/master/blockchains/${networkName}/assets/${address}/logo.png`
    : undefined
}

export function buildPartialCurrencyInfo(commonBase: Currency): CurrencyInfo {
  const logoUrl = commonBase.isNative
    ? getNativeLogoURI(commonBase.chainId)
    : getTokenLogoURI(commonBase.chainId, commonBase.address)

  return buildCurrencyInfo({
    currency: commonBase,
    logoUrl,
    safetyInfo: {
      protectionResult: ProtectionResult.Benign,
      tokenList: 'hardcoded-common-bases',
      attackType: null,
      warnings: null,
    },
    isSpam: false,
  } as CurrencyInfo)
}

export function getTokenLogoTableItem(
  chainId: UniverseChainId,
  address: string,
  table: LogoTable,
): CurrencyInfo | undefined {
  if (isCelo(chainId) && isSameAddress(address, nativeOnChain(chainId).wrapped.address)) {
    return buildPartialCurrencyInfo({
      ...nativeOnChain(chainId).wrapped,
      logoUrl: CELO_LOGO,
      safetyLevel: ProtectionResult.Benign,
      feeData: null,
    } as CurrencyInfo)
  }
  const networkName = getChainInfo(chainId).assetRepoNetworkName
  if (!networkName) {
    return undefined
  }
  return table[`${networkName.toUpperCase()}_${address.toLowerCase()}`] as CurrencyInfo | undefined
}

export function getCommonBase(chainId?: number, isNative?: boolean, address?: string): CurrencyInfo | undefined {
  if (!address || !chainId) {
    return undefined
  }
  return COMMON_BASES[chainId]?.find(
    (base) =>
      (base.currency.isNative && isNative) || (base.currency.isToken && isSameAddress(base.currency.address, address)),
  )
}

export function isAlwaysShowToken(token: CurrencyInfo): boolean {
  return alwaysShowList.some((t) => t.address === token.address && t.chainId === token.chainId)
}
