// Abstract DEX Subgraph API for dynamic pool discovery

import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { getAbstractSubgraphs } from 'uniswap/src/constants/abstractContracts'

// GraphQL queries based on tested schema
const V2_POOLS_QUERY = `
  query GetV2Pools($tokenIn: String!, $tokenOut: String!) {
    pairs(
      where: {
        or: [
          { token0: $tokenIn, token1: $tokenOut }
          { token0: $tokenOut, token1: $tokenIn }
        ]
      }
      orderBy: reserveUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
    }
  }
`

const V2_MULTI_HOP_QUERY = `
  query GetV2MultiHopPools($tokens: [String!]!) {
    pairs(
      where: {
        and: [
          {
            or: [
              { token0_in: $tokens }
              { token1_in: $tokens }
            ]
          }
          { reserveUSD_gt: "100" }
        ]
      }
      first: 50
      orderBy: reserveUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
    }
  }
`

const V3_POOLS_QUERY = `
  query GetV3Pools($tokenIn: String!, $tokenOut: String!) {
    pools(
      where: {
        or: [
          { token0: $tokenIn, token1: $tokenOut }
          { token0: $tokenOut, token1: $tokenIn }
        ]
      }
      orderBy: totalValueLockedUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
    }
  }
`

// Query to fetch top pools by TVL (for search modal)
const V2_TOP_POOLS_QUERY = `
  query GetTopV2Pools($first: Int!) {
    pairs(
      first: $first
      orderBy: reserveUSD
      orderDirection: desc
      where: { reserveUSD_gt: "1000" }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
    }
  }
`

const V3_TOP_POOLS_QUERY = `
  query GetTopV3Pools($first: Int!) {
    pools(
      first: $first
      orderBy: totalValueLockedUSD
      orderDirection: desc
      where: { totalValueLockedUSD_gt: "1000" }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
    }
  }
`

const GET_GAUGES_QUERY = `
  query GetGauges {
    gauges(first: 100, where: { isAlive: true }) {
      id
      pool
    }
  }
`

// Query to fetch tick data for liquidity depth chart
const V3_POOL_TICKS_QUERY = `
  query GetPoolTicks($poolAddress: String!, $skip: Int!) {
    ticks(
      where: { poolAddress: $poolAddress }
      orderBy: tickIdx
      orderDirection: asc
      first: 1000
      skip: $skip
    ) {
      tickIdx
      liquidityGross
      liquidityNet
      price0
      price1
    }
  }
`

const V3_POOL_PRICE_HISTORY_QUERY = `
  query PoolPriceHistory($poolId: String!, $from: Int!, $pageSize: Int!, $skip: Int!) {
    poolDayDatas(
      first: $pageSize
      skip: $skip
      where: { pool: $poolId, date_gte: $from }
      orderBy: date
      orderDirection: asc
    ) {
      date
      token0Price
      token1Price
      open
      high
      low
      close
    }
  }
`

// Types for subgraph responses
export interface V2PoolData {
  id: string
  token0: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  token1: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  reserve0: string // Already formatted (not raw wei)
  reserve1: string // Already formatted (not raw wei)
  reserveUSD: string
  stable?: boolean
}

export interface V3PoolData {
  id: string
  token0: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  token1: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  tickSpacing: string
  liquidity: string
  sqrtPrice: string
  tick: string
  totalValueLockedUSD: string
  totalValueLockedToken0: string
  totalValueLockedToken1: string
}

export interface TickData {
  tickIdx: string
  liquidityGross: string
  liquidityNet: string
  price0: string
  price1: string
}

export interface PoolDayData {
  date: string
  token0Price: string
  token1Price: string
  open?: string
  high?: string
  low?: string
  close?: string
}

// Fetch V2 pools for specific token pair
export async function fetchV2Pools(tokenIn: string, tokenOut: string, chainId: UniverseChainId = UniverseChainId.Mainnet): Promise<V2PoolData[]> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)
    const response = await fetch(subgraphs.v2, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: V2_POOLS_QUERY,
        variables: { 
          tokenIn: tokenIn.toLowerCase(), 
          tokenOut: tokenOut.toLowerCase() 
        },
      }),
    })

    const data = await response.json()
    
    if (data.errors) {
      console.error('V2 Subgraph errors:', data.errors)
      return []
    }

    return data.data?.pairs || []
  } catch (error) {
    console.error('Failed to fetch V2 pools:', error)
    return []
  }
}

