// Fetch pools for multi-hop routing including common base pairs
export async function fetchPoolsForRouting(
  tokenIn: string,
  tokenOut: string,
  chainId: UniverseChainId = UniverseChainId.Mainnet,
  includeMultiHop = true
): Promise<{ v2Pools: V2PoolData[]; v3Pools: V3PoolData[] }> {

  // Common base tokens for multi-hop routing
  const COMMON_BASES = [
    '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d', // WETH
    '0x698f98ab816670692fa9dd8e1486ea0fd253e996', // USDC
  ]

  const queries = []

  // Direct pairs
  queries.push(fetchV2Pools(tokenIn, tokenOut, chainId))
  queries.push(fetchV3Pools(tokenIn, tokenOut, chainId))

  // Multi-hop pairs if enabled
  if (includeMultiHop) {
    const relevantTokens = [tokenIn, tokenOut, ...COMMON_BASES]
      .map(t => t.toLowerCase())
      // Remove duplicates
      .filter((token, index, self) => self.indexOf(token) === index)

    // Fetch all pools involving these tokens for multi-hop
    queries.push(fetchV2MultiHopPools(relevantTokens, chainId))
  }

  try {
    const results = await Promise.all(queries)

    let v2Pools: V2PoolData[] = results[0] || []
    let v3Pools: V3PoolData[] = results[1] || []

    // Add multi-hop pools if available
    if (includeMultiHop && results[2]) {
      v2Pools = [...v2Pools, ...results[2]]
    }

    // Remove duplicates
    v2Pools = v2Pools.filter((pool, index, self) =>
      index === self.findIndex(p => p.id === pool.id)
    )
    v3Pools = v3Pools.filter((pool, index, self) =>
      index === self.findIndex(p => p.id === pool.id)
    )


    return { v2Pools, v3Pools }
  } catch (error) {
    console.error('Failed to fetch pools for routing:', error)
    return { v2Pools: [], v3Pools: [] }
  }
}

// Optimized lazy pool loading - fetches only relevant pools for routing
export async function fetchPoolsLazy(
  tokenIn: string,
  tokenOut: string,
  chainId: UniverseChainId = UniverseChainId.Mainnet,
  commonBases: string[] = []
): Promise<{ v2Pools: V2PoolData[]; v3Pools: V3PoolData[] }> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)
    const tokenInLower = tokenIn.toLowerCase()
    const tokenOutLower = tokenOut.toLowerCase()

    // Build list of relevant tokens: input, output, and common bases
    const relevantTokens = [tokenInLower, tokenOutLower, ...commonBases.map(t => t.toLowerCase())]
      .filter((token, index, self) => self.indexOf(token) === index) // Remove duplicates

    console.log('[Pool Lazy Load] Fetching pools for tokens:', relevantTokens)

    // Optimized V2 query: fetch only pools involving relevant tokens
    const v2Query = `
      query GetRelevantV2Pools($tokens: [String!]!) {
        pairs(
          where: {
            and: [
              {
                or: [
                  { token0_in: $tokens }
                  { token1_in: $tokens }
                ]
              }
              { reserveUSD_gt: "10" }
            ]
          }
          first: 100
          orderBy: reserveUSD
          orderDirection: desc
        ) {
          id
          token0 { id symbol decimals name }
          token1 { id symbol decimals name }
          reserve0
          reserve1
          reserveUSD
          stable
        }
      }
    `

    // Optimized V3 query: fetch only pools involving relevant tokens
    const v3Query = `
      query GetRelevantV3Pools($tokens: [String!]!) {
        pools(
          where: {
            and: [
              {
                or: [
                  { token0_in: $tokens }
                  { token1_in: $tokens }
                ]
              }
              { liquidity_gt: "0" }
            ]
          }
          first: 100
          orderBy: totalValueLockedUSD
          orderDirection: desc
        ) {
          id
          token0 { id symbol decimals name }
          token1 { id symbol decimals name }
          tickSpacing
          liquidity
          sqrtPrice
          tick
          totalValueLockedUSD
          totalValueLockedToken0
          totalValueLockedToken1
        }
      }
    `

    // Fetch both in parallel
    const [v2Response, v3Response] = await Promise.all([
      fetch(subgraphs.v2, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          query: v2Query,
          variables: { tokens: relevantTokens },
        }),
      }),
      fetch(subgraphs.v3, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          query: v3Query,
          variables: { tokens: relevantTokens },
        }),
      }),
    ])

    const [v2Data, v3Data] = await Promise.all([
      v2Response.json().catch(() => ({ data: { pairs: [] } })),
      v3Response.json().catch(() => ({ data: { pools: [] } })),
    ])

    if (v2Data.errors) {
      console.error('[Pool Lazy Load] V2 subgraph errors:', v2Data.errors)
    }

    if (v3Data.errors) {
      console.error('[Pool Lazy Load] V3 subgraph errors:', v3Data.errors)
    }

    const v2Pools = v2Data.data?.pairs || []
    const v3Pools = v3Data.data?.pools || []

    console.log('[Pool Lazy Load] Fetched pools:', { v2Count: v2Pools.length, v3Count: v3Pools.length })

    return { v2Pools, v3Pools }
  } catch (error) {
    console.error('[Pool Lazy Load] Failed to fetch pools:', error)
    return { v2Pools: [], v3Pools: [] }
  }
}

// Query to fetch single token data
const TOKEN_QUERY = `
  query GetToken($tokenAddress: String!) {
    tokens(where: { id: $tokenAddress }) {
      id
      symbol
      decimals
      name
    }
  }
`

// Fetch token data from Abstract subgraphs
export async function fetchTokenData(tokenAddress: string, chainId: UniverseChainId = UniverseChainId.Mainnet): Promise<{
  id: string
  symbol: string
  decimals: string
  name: string
} | null> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)

    // Try V2 subgraph first
    const v2Response = await fetch(subgraphs.v2, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: TOKEN_QUERY,
        variables: { tokenAddress: tokenAddress.toLowerCase() },
      }),
    })

    const v2Data = await v2Response.json()

    if (v2Data.data?.tokens?.[0]) {
      return v2Data.data.tokens[0]
    }

    // Try V3 subgraph as fallback
    const v3Response = await fetch(subgraphs.v3, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: TOKEN_QUERY,
        variables: { tokenAddress: tokenAddress.toLowerCase() },
      }),
    })

    const v3Data = await v3Response.json()
    
    if (v3Data.data?.tokens?.[0]) {
      return v3Data.data.tokens[0]
    }

    return null
  } catch (error) {
    console.error('Failed to fetch token data from Abstract subgraphs:', error)
    return null
  }
}

