// Fetch top pools by TVL for search modal
export async function fetchTopPoolsByTVL(limit: number = 15, chainId: UniverseChainId = UniverseChainId.Mainnet): Promise<{
  v2Pools: V2PoolData[]
  v3Pools: V3PoolData[]
  gauges: Map<string, string>
}> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)

    const [v2Response, v3Response, gaugesResponse] = await Promise.all([
      fetch(subgraphs.v2, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: V2_TOP_POOLS_QUERY,
          variables: { first: Math.ceil(limit * 0.6) }, // 60% V2 pools
        }),
      }),
      fetch(subgraphs.v3, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: V3_TOP_POOLS_QUERY,
          variables: { first: Math.ceil(limit * 0.4) }, // 40% V3 pools
        }),
      }),
      fetch(subgraphs.gauges, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: GET_GAUGES_QUERY,
        }),
      }),
    ])

    const [v2Data, v3Data, gaugesData] = await Promise.all([
      v2Response.json(),
      v3Response.json(),
      gaugesResponse.json(),
    ])

    if (v2Data.errors) {
      console.error('V2 Top pools subgraph errors:', v2Data.errors)
    }

    if (v3Data.errors) {
      console.error('V3 Top pools subgraph errors:', v3Data.errors)
    }

    if (gaugesData.errors) {
      console.error('Gauges subgraph errors:', gaugesData.errors)
    }

    const v2Pools: V2PoolData[] = v2Data.data?.pairs || []
    const v3Pools: V3PoolData[] = v3Data.data?.pools || []

    // Create a map of pool addresses to gauge addresses
    const gaugesMap = new Map<string, string>()
    if (gaugesData.data?.gauges) {
      gaugesData.data.gauges.forEach((gauge: { id: string; pool: string }) => {
        gaugesMap.set(gauge.pool.toLowerCase(), gauge.id)
      })
    }

    return { v2Pools, v3Pools, gauges: gaugesMap }
  } catch (error) {
    console.error('Failed to fetch top pools by TVL:', error)
    return { v2Pools: [], v3Pools: [], gauges: new Map() }
  }
}

// Fetch tick data for liquidity depth chart with pagination support
export async function fetchV3PoolTicks(
  poolAddress: string,
  chainId: UniverseChainId = UniverseChainId.Mainnet,
  skip: number = 0
): Promise<TickData[]> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)
    const response = await fetch(subgraphs.v3, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: V3_POOL_TICKS_QUERY,
        variables: {
          poolAddress: poolAddress.toLowerCase(),
          skip,
        },
      }),
    })

    const data = await response.json()

    if (data.errors) {
      console.error('V3 Pool ticks subgraph errors:', data.errors)
      return []
    }

    return data.data?.ticks || []
  } catch (error) {
    console.error('Failed to fetch V3 pool ticks:', error)
    return []
  }
}

// Fetch all ticks for a pool (handles pagination automatically)
export async function fetchAllV3PoolTicks(
  poolAddress: string,
  chainId: UniverseChainId = UniverseChainId.Mainnet
): Promise<TickData[]> {
  const allTicks: TickData[] = []
  let skip = 0
  const batchSize = 1000

  try {
    while (true) {
      const ticks = await fetchV3PoolTicks(poolAddress, chainId, skip)

      if (ticks.length === 0) {
        break
      }

      allTicks.push(...ticks)

      // If we got less than batchSize results, we've fetched all ticks
      if (ticks.length < batchSize) {
        break
      }

      skip += batchSize
    }

    console.log(`[Tick Data] Fetched ${allTicks.length} ticks for pool ${poolAddress}`)
    return allTicks
  } catch (error) {
    console.error('Failed to fetch all V3 pool ticks:', error)
    return allTicks // Return whatever we managed to fetch
  }
}

export async function fetchPoolPriceHistory(
  poolAddress: string,
  chainId: UniverseChainId = UniverseChainId.Mainnet,
  from: number = 0,
  pageSize: number = 1000,
  skip: number = 0
): Promise<PoolDayData[]> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)
    const response = await fetch(subgraphs.v3, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        query: V3_POOL_PRICE_HISTORY_QUERY,
        variables: {
          poolId: poolAddress.toLowerCase(),
          from,
          pageSize,
          skip,
        },
      }),
    })

    const data = await response.json()

    if (data.errors) {
      console.error('V3 Pool price history subgraph errors:', data.errors)
      return []
    }

    return data.data?.poolDayDatas || []
  } catch (error) {
    console.error('Failed to fetch V3 pool price history:', error)
    return []
  }
}

export async function fetchAllPoolPriceHistory(
  poolAddress: string,
  chainId: UniverseChainId = UniverseChainId.Mainnet,
  from: number = 0
): Promise<PoolDayData[]> {
  const allEntries: PoolDayData[] = []
  const pageSize = 1000
  let skip = 0

  try {
    while (true) {
      const entries = await fetchPoolPriceHistory(poolAddress, chainId, from, pageSize, skip)
      if (!entries.length) {
        break
      }

      allEntries.push(...entries)

      if (entries.length < pageSize) {
        break
      }

      skip += pageSize
    }

    return allEntries
  } catch (error) {
    console.error('Failed to fetch all pool price history:', error)
    return allEntries
  }
}
