import { BigNumber, ethers } from 'ethers'
import { FEE_TO_TICK_SPACING } from 'uniswap/src/constants/abstractContracts'
import { CurrencyAmount, TradeType } from '@uniswap/sdk-core'

export interface V3TransactionParams {
  inputAmount: CurrencyAmount<any>
  outputAmount: CurrencyAmount<any>
  path: string[]
  // Optional per-hop fees (hundredths of a bip, e.g., 3000 = 0.3%).
  // When provided, used to encode the V3 path for multi-hop transactions.
  fees?: number[]
  tradeType: TradeType
  tickSpacing?: number
  // Optional per-hop tick spacings (e.g., 1, 100, 200, 2000) aligned with fees
  tickSpacings?: number[]
  slippageTolerance: number // in basis points
  deadline: number
  recipient: string
  shouldInputEth: boolean
  shouldOutputEth: boolean
}

export interface V3TransactionResult {
  calldata: string
  value: string
  targetRouter: string
  success: boolean
  error?: string
}

export class V3TransactionBuilder {
  
  /**
   * Build V3 exact input transaction
   */
  buildExactInputTransaction(params: V3TransactionParams): V3TransactionResult {
    try {
      const {
        inputAmount,
        outputAmount,
        path,
        tickSpacing = 200, // Default to 200 (0.3% fee equivalent)
        slippageTolerance,
        deadline,
        recipient,
        shouldInputEth,
        shouldOutputEth
      } = params

      const amountIn = inputAmount.quotient.toString()
      const amountOutMin = this.calculateMinimumOutput(outputAmount, slippageTolerance)

      if (path.length === 2) {
        // Single hop
        return this.buildSingleHopTransaction(
          path[0], path[1], tickSpacing, amountIn, amountOutMin, 
          recipient, deadline, shouldInputEth, shouldOutputEth
        )
      } else {
        // Multi-hop
        console.log('[V3Routing] V3Builder EI multi-hop', { path, fees: params.fees, tickSpacings: params.tickSpacings })
        return this.buildMultiHopTransaction(
          path, params.fees, amountIn, amountOutMin, recipient, deadline, shouldInputEth, shouldOutputEth, params.tickSpacings
        )
      }
    } catch (error) {
      return {
        calldata: '',
        value: '0',
        targetRouter: '',
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      }
    }
  }

  /**
   * Build V3 exact output transaction
   */
  buildExactOutputTransaction(params: V3TransactionParams): V3TransactionResult {
    try {
      const {
        inputAmount,
        outputAmount,
        path,
        tickSpacing = 200,
        slippageTolerance,
        deadline,
        recipient,
        shouldInputEth,
        shouldOutputEth
      } = params

      const amountOut = outputAmount.quotient.toString()
      const amountInMax = this.calculateMaximumInput(inputAmount, slippageTolerance)

      if (path.length === 2) {
        // Single hop exact output
        return this.buildSingleHopExactOutputTransaction(
          path[0], path[1], tickSpacing, amountOut, amountInMax,
          recipient, deadline, shouldInputEth, shouldOutputEth
        )
      } else {
        // Multi-hop exact output
        console.log('[V3Routing] V3Builder EO multi-hop', { path, fees: params.fees, tickSpacings: params.tickSpacings })
        return this.buildMultiHopExactOutputTransaction(
          path, params.fees, amountOut, amountInMax, recipient, deadline, shouldInputEth, shouldOutputEth, params.tickSpacings
        )
      }
    } catch (error) {
      return {
        calldata: '',
        value: '0',
        targetRouter: '',
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      }
    }
  }

  private calculateMinimumOutput(outputAmount: CurrencyAmount<any>, slippageTolerance: number): string {
    return BigNumber.from(outputAmount.quotient.toString())
      .mul(10000 - slippageTolerance)
      .div(10000)
      .toString()
  }

  private calculateMaximumInput(inputAmount: CurrencyAmount<any>, slippageTolerance: number): string {
    return BigNumber.from(inputAmount.quotient.toString())
      .mul(10000 + slippageTolerance)
      .div(10000)
      .toString()
  }

  private buildSingleHopTransaction(
    tokenIn: string,
    tokenOut: string,
    tickSpacing: number,
    amountIn: string,
    amountOutMin: string,
    recipient: string,
    deadline: number,
    shouldInputEth: boolean,
    shouldOutputEth: boolean
  ): V3TransactionResult {
    const iface = new ethers.utils.Interface([
      'function exactInputSingle((address tokenIn, address tokenOut, int24 tickSpacing, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)'
    ])

    const calldata = iface.encodeFunctionData('exactInputSingle', [{
      tokenIn,
      tokenOut,
      tickSpacing,
      recipient,
      deadline,
      amountIn,
      amountOutMinimum: amountOutMin,
      sqrtPriceLimitX96: 0
    }])

    const value = shouldInputEth ? amountIn : '0'

    return {
      calldata,
      value,
      targetRouter: '', // Will be set by caller
      success: true
    }
  }

  private buildSingleHopExactOutputTransaction(
    tokenIn: string,
    tokenOut: string,
    tickSpacing: number,
    amountOut: string,
    amountInMax: string,
    recipient: string,
    deadline: number,
    shouldInputEth: boolean,
    shouldOutputEth: boolean
  ): V3TransactionResult {
    const iface = new ethers.utils.Interface([
      'function exactOutputSingle((address tokenIn, address tokenOut, int24 tickSpacing, address recipient, uint256 deadline, uint256 amountOut, uint256 amountInMaximum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountIn)'
    ])

    const calldata = iface.encodeFunctionData('exactOutputSingle', [{
      tokenIn,
      tokenOut,
      tickSpacing,
      recipient,
      deadline,
      amountOut,
      amountInMaximum: amountInMax,
      sqrtPriceLimitX96: 0
    }])

    const value = shouldInputEth ? amountInMax : '0'

    return {
      calldata,
      value,
      targetRouter: '', // Will be set by caller
      success: true
    }
  }

  private buildMultiHopTransaction(
    path: string[],
    fees: number[] | undefined,
    amountIn: string,
    amountOutMin: string,
    recipient: string,
    deadline: number,
    shouldInputEth: boolean,
    shouldOutputEth: boolean,
    tickSpacings?: number[]
  ): V3TransactionResult {
    const iface = new ethers.utils.Interface([
      'function exactInput((bytes path, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum)) external payable returns (uint256 amountOut)'
    ])

    // Encode path with per-hop tickSpacings if available, otherwise derive from fees
    const encodedPath = this.encodePath(path, fees, tickSpacings)
    console.log('[V3Routing] V3Builder EI encodedPath', { encodedPath })

    const calldata = iface.encodeFunctionData('exactInput', [{
      path: encodedPath,
      recipient,
      deadline,
      amountIn,
      amountOutMinimum: amountOutMin
    }])

    const value = shouldInputEth ? amountIn : '0'

    return {
      calldata,
      value,
      targetRouter: '', // Will be set by caller
      success: true
    }
  }

  private buildMultiHopExactOutputTransaction(
    path: string[],
    fees: number[] | undefined,
    amountOut: string,
    amountInMax: string,
    recipient: string,
    deadline: number,
    shouldInputEth: boolean,
    shouldOutputEth: boolean,
    tickSpacings?: number[]
  ): V3TransactionResult {
    const iface = new ethers.utils.Interface([
      'function exactOutput((bytes path, address recipient, uint256 deadline, uint256 amountOut, uint256 amountInMaximum)) external payable returns (uint256 amountIn)'
    ])

    // For exact output, path needs to be reversed
    const reversedPath = [...path].reverse()
    const reversedFees = fees ? [...fees].reverse() : undefined
    const encodedPath = this.encodePath(reversedPath, reversedFees, tickSpacings?.slice()?.reverse())
    console.log('[V3Routing] V3Builder EO encodedPath', { encodedPath })

    const calldata = iface.encodeFunctionData('exactOutput', [{
      path: encodedPath,
      recipient,
      deadline,
      amountOut,
      amountInMaximum: amountInMax
    }])

    const value = shouldInputEth ? amountInMax : '0'

    return {
      calldata,
      value,
      targetRouter: '', // Will be set by caller
      success: true
    }
  }

  private encodePath(path: string[], fees?: number[], tickSpacings?: number[]): string {
    // Encode a V3 path: address(20) | tickSpacing(3) | address(20) | tickSpacing(3) | address(20)
    // Abstract DEX expects tickSpacing in the 3-byte slot (not fee bips).
    if (path.length < 2) {
      throw new Error('encodePath: path too short')
    }

    const hops = path.length - 1
    // Build per-hop tickSpacing array: prefer explicit tickSpacings; else derive from fees; else default 200
    const spacingPerHop: number[] = []
    for (let i = 0; i < hops; i++) {
      if (tickSpacings && typeof tickSpacings[i] === 'number') {
        spacingPerHop.push(tickSpacings[i]!)
      } else if (fees && typeof fees[i] === 'number') {
        const derived = (FEE_TO_TICK_SPACING as any)[fees[i]!] ?? 200
        spacingPerHop.push(derived)
      } else {
        spacingPerHop.push(200)
      }
    }

    const parts: string[] = []
    // First token address
    parts.push(path[0].toLowerCase().replace(/^0x/, ''))
    for (let i = 0; i < hops; i++) {
      const spacingHex = spacingPerHop[i].toString(16)
      // 3 bytes => 6 hex chars; left pad
      parts.push(spacingHex.padStart(6, '0'))
      parts.push(path[i + 1].toLowerCase().replace(/^0x/, ''))
    }
    return '0x' + parts.join('')
  }
}
